use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut total_time = 0;
    let mut server_status = vec![0; input.len()];

    for (arrival, duration) in input.iter() {
        let start_time = arrival as i64;
        let end_time = start_time + duration as i64;

        if server_status[start_time] == 0 {
            server_status[start_time] = 1;
            total_time += end_time - start_time;
        }
    }

    serde_json::Value::Object {
        properties: vec![
            ("total_time", serde_json::Value::Number(total_time as i64)),
        ],
    }
}
